import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

import { Root } from "./Package.server";

// The marketplace index is generated by the monorepo over the same packages.
// The site reads the generated file rather than restating it, so a renamed
// bundle title appears here on the next build.

export interface Bundle {
	Name: string;
	Title: string;
	Summary: string;
}

export interface Group {
	Id: string;
	Label: string;
	Bundle: Bundle[];
}

export interface Marketplace {
	Title: string;
	Description: string;
	Group: Group[];
}

interface Manifest {
	title?: { en?: string };
	description?: { en?: string };
	metadata?: { categories?: Record<string, { title?: { en?: string } }> };
	plugins?: {
		name?: string;
		title?: { en?: string };
		description?: { en?: string };
		metadata?: { category?: string };
	}[];
}

function Summarize(Text: string): string {
	const Head = Text.split("(")[0] ?? Text;
	const Sentence = Head.split(/(?:[.!?]\s)|(?:\s[\u2014\u2013]\s)/)[0] ?? Head;

	return Sentence.trim();
}

function Load(): Marketplace {
	const Path = join(Root, "marketplace.json");

	if (!existsSync(Path)) {
		return { Title: "", Description: "", Group: [] };
	}

	const Index = JSON.parse(readFileSync(Path, "utf8")) as Manifest;
	const Categories = Index.metadata?.categories ?? {};
	const Group: Group[] = [];

	for (const [Id, Category] of Object.entries(Categories)) {
		const Bundle = (Index.plugins ?? [])
			.filter((Entry) => Entry.metadata?.category === Id)
			.map((Entry) => ({
				Name: Entry.name ?? "",
				Title: Entry.title?.en ?? Entry.name ?? "",
				Summary: Summarize(Entry.description?.en ?? ""),
			}))
			.sort((Left, Right) => Left.Title.localeCompare(Right.Title));

		if (Bundle.length > 0) {
			Group.push({ Id, Label: Category.title?.en ?? Id, Bundle });
		}
	}

	return {
		Title: Index.title?.en ?? "Marketplace",
		Description: Index.description?.en ?? "",
		Group,
	};
}

export const Marketplace = Load();

export function SelectGroup(Id: string): Group | undefined {
	return Marketplace.Group.find((Entry) => Entry.Id === Id);
}

export default Marketplace;
